type Language = "ar" | "en";
const STORAGE_KEY = "hpc-guide-language";

function getSavedLanguage(): Language {
  try {
    return localStorage.getItem(STORAGE_KEY) === "en" ? "en" : "ar";
  } catch {
    return "ar";
  }
}


